import sys
sys.setrecursionlimit(10000)

def lps(s):
    def helper(s, i, j):
        if i == j:
            return 1
        if i > j:
            return 0
        if s[i] == s[j]:
            return 2 + helper(s, i + 1, j - 1)
        return max(helper(s, i + 1, j), helper(s, i, j - 1))

    return helper(s, 0, len(s) - 1)

